const goalIcons:Record<string,LucideIcon>={sun:Sun,shield:ShieldCheck,home:House,plane:Plane,sparkles:Sparkles};
const pageTitles:Record<Page,string>={plan:"Votre équilibre, mois après mois.",overview:"Vue d’ensemble",transactions:"Vos opérations",recurring:"Un quotidien bien anticipé.",accounts:"Chaque compte à sa place.",goals:"De la place pour vos projets.",settings:"PECULE, à votre façon."};
nav.push({id:"plan",label:"Mon équilibre 50/30/20",short:"Équilibre",icon:LayoutGrid});
const uid=()=>crypto.randomUUID();
const inputAmount=(cents:number)=>String(cents/100);
function downloadFile(content:string,name:string,type:string){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement("a");a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function CategoryIcon({category,size=19}:{category:string;size?:number}){const meta=categoryInfo[category]??{icon:Wallet,color:"#7e8ba0",background:"#f0f2f5"},Icon=meta.icon;return <span className="category-icon" style={{color:meta.color,background:meta.background}}><Icon size={size} strokeWidth={1.7}/></span>;}
function Empty({icon:Icon,title,description,action}:{icon:LucideIcon;title:string;description:string;action?:ReactNode}){return <div className="empty"><span className="empty-icon"><Icon size={26} strokeWidth={1.5}/></span><h3>{title}</h3><p>{description}</p>{action}</div>;}
function AmountInput({name,defaultValue,required=true,positive=true,...accessibility}:{name:string;defaultValue?:number;required?:boolean;positive?:boolean;id?:string;"aria-invalid"?:boolean;"aria-describedby"?:string}){return <span className="amount-input"><input {...accessibility} name={name} type="number" inputMode="decimal" step="0.01" min={positive?"0.01":undefined} max="1000000000" defaultValue={defaultValue===undefined?undefined:inputAmount(defaultValue)} required={required} placeholder="0,00"/><span>€</span></span>;}
function dateLabel(date:string,today:string){return date===today?"Aujourd’hui":date===shiftDate(today,-1)?"Hier":parseDate(date).toLocaleDateString("fr-FR",{weekday:"long",day:"numeric",month:"long"});}

export default function BudgetApp({user}:{user:{name:string|null;email:string}|null}){
  const [today,setToday]=useState(todayISO);
  const [merchantDirection,setMerchantDirection]=useState("expense");
  const [budget,setBudget]=useState<Budget>(()=>demoBudget(todayISO()));
  const [demo,setDemo]=useState(true),[hasBudget,setHasBudget]=useState(false),[loaded,setLoaded]=useState(false);
  const [page,setPage]=useState<Page>("overview"),[modal,setModal]=useState<Modal|null>(null),[saving,setSaving]=useState(false);
  const [online,setOnline]=useState(true),[loadError,setLoadError]=useState(false),[error,setError]=useState(""),[toast,setToast]=useState("");
  const [hidden,setHidden]=useState(false),[query,setQuery]=useState(""),[typeFilter,setTypeFilter]=useState("all"),[accountFilter,setAccountFilter]=useState("all"),[month,setMonth]=useState(todayISO().slice(0,7));
  const [sync]=useState(()=>new BudgetSync());
  const [sessionExpired,setSessionExpired]=useState(false);
  const saveLock=useRef(false),dialogRef=useRef<HTMLDivElement>(null),previousFocus=useRef<HTMLElement|null>(null);
  const [installPrompt,setInstallPrompt]=useState<{prompt:()=>Promise<void>;userChoice:Promise<{outcome:string}>}|null>(null);
  const load=useCallback(async(quiet=false)=>{
    if(!user){setLoaded(true);return;}
    try{const result=await sync.load();if(!result)return;if(result.budget){setBudget(materialize(result.budget));setDemo(false);setHasBudget(true);}setSessionExpired(false);setLoadError(false);}
    catch(e){setLoadError(true);if(e instanceof BudgetRequestError&&e.status===401)setSessionExpired(true);if(!quiet)setToast(e instanceof Error?e.message:"Impossible de charger les données.");}
    finally{setLoaded(true);}
  },[user,sync]);
  useEffect(()=>{void load();setHidden(localStorage.getItem("pecule-hide-amounts")==="1");const off=()=>setOnline(false),on=()=>{setOnline(true);if(!saveLock.current)void load(true);};setOnline(navigator.onLine);window.addEventListener("online",on);window.addEventListener("offline",off);const tick=setInterval(()=>setToday(todayISO()),60000);if("serviceWorker" in navigator)void navigator.serviceWorker.register("/sw.js").catch(()=>{});const prompt=(e:Event)=>{e.preventDefault();setInstallPrompt(e as unknown as typeof installPrompt);};window.addEventListener("beforeinstallprompt",prompt);return()=>{clearInterval(tick);window.removeEventListener("online",on);window.removeEventListener("offline",off);window.removeEventListener("beforeinstallprompt",prompt);};},[load]);
  useEffect(()=>{if(demo || modal || !online)return;const refresh=()=>{if(document.visibilityState==="visible"&&!saveLock.current)void load(true);};const timer=setInterval(refresh,30000);document.addEventListener("visibilitychange",refresh);return()=>{clearInterval(timer);document.removeEventListener("visibilitychange",refresh);};},[demo,modal,online,load]);
  useEffect(()=>{const params=new URLSearchParams(window.location.search);if(params.get("connection")==="google"){setPage("settings");const message=googleErrorMessage(params.get("error"));if(message)setToast(message);}},[]);
  useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(""),6500);return()=>clearTimeout(t);},[toast]);
  useEffect(()=>{if(!modal){setError("");previousFocus.current?.focus();return;}previousFocus.current=document.activeElement as HTMLElement;const prev=document.body.style.overflow;document.body.style.overflow="hidden";requestAnimationFrame(()=>(dialogRef.current?.querySelector<HTMLElement>("input,select,textarea")??dialogRef.current?.querySelector<HTMLElement>("button"))?.focus());const onKey=(e:KeyboardEvent)=>{if(e.key==="Escape"&&!saveLock.current)setModal(null);if(e.key==="Tab"){const items=dialogRef.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]');if(!items?.length)return;const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};window.addEventListener("keydown",onKey);return()=>{document.body.style.overflow=prev;window.removeEventListener("keydown",onKey);};},[modal]);
  const b=useMemo(()=>materialize(budget,today),[budget,today]);
  const o=useMemo(()=>overview(b,today),[b,today]);
  const m=(n:number,decimals=true)=>hidden?"•••• €":money(n,decimals);
  const navigate=(p:Page)=>{setPage(p);setQuery("");window.scrollTo({top:0,behavior:"smooth"});};
  const open=(value:Modal)=>{setError("");if(value.type==="transaction"||value.type==="rule")setMerchantDirection(value.item&&value.item.amount>0?"income":value.type==="transaction"?value.direction??"expense":"expense");setModal(value);};
  async function save(next:Budget,message="C’est enregistré.",real=false):Promise<boolean>{
    if(saveLock.current)return false;
    if(demo&&!real){setBudget(materialize(next,today));setToast(message+" · Démonstration");return true;}
    if(!online){setError("Reconnectez-vous à Internet pour enregistrer vos modifications.");setToast("Reconnectez-vous pour enregistrer vos modifications.");return false;}
    if(!user){window.location.assign("/sign-in");return false;}
    if(loadError){setError("Rechargez d’abord votre budget pour éviter de remplacer vos données.");setToast("Rechargez votre budget avant de le modifier.");return false;}
    saveLock.current=true;setSaving(true);setError("");
    try{await sync.save(materialize(next,today));setBudget(materialize(next,today));setDemo(false);setHasBudget(true);setToast(message);return true;}
    catch(e){if(e instanceof BudgetRequestError&&(e.status===401||e.status===409)){setLoadError(true);if(e.status===401)setSessionExpired(true);}const message=e instanceof Error?e.message:"Impossible d’enregistrer.";setError(message);setToast(message);return false;}
    finally{saveLock.current=false;setSaving(false);}
  }
  const editItem=<T extends {id:string}>(list:T[],item:T)=>list.some(r=>r.id===item.id)?list.map(r=>r.id===item.id?item:r):[...list,item];
  function remove(kind:"account"|"transaction"|"rule"|"goal",id:string){
    if(kind==="account"&&(b.transactions.some(t=>t.accountId===id)||b.rules.some(t=>t.accountId===id))){setToast("Ce compte contient des opérations ou des récurrences. Supprimez-les d’abord.");return;}
    open({type:"confirm",title:kind==="transaction"?"Supprimer cette opération ?":kind==="rule"?"Supprimer cette récurrence ?":kind==="goal"?"Supprimer cet objectif ?":"Supprimer ce compte ?",message:kind==="rule"?"Les opérations déjà enregistrées seront conservées. Les prochaines échéances seront supprimées.":kind==="goal"?"Les virements déjà enregistrés seront conservés. L’objectif et sa réserve seront supprimés.":"Cette action est définitive. Les soldes et les prévisions seront recalculés.",action:async()=>{
      const next=structuredClone(b);
      if(kind==="account")next.accounts=next.accounts.filter(a=>a.id!==id);
      if(kind==="rule")next.rules=next.rules.filter(a=>a.id!==id);
      if(kind==="goal")next.goals=next.goals.filter(a=>a.id!==id);
      if(kind==="transaction"){const t=next.transactions.find(a=>a.id===id);const removed=next.transactions.filter(a=>a.id===id||(t?.transferId&&a.transferId===t.transferId));next.transactions=next.transactions.filter(a=>!removed.includes(a));for(const item of removed){if(item.ruleId){const r=next.rules.find(r=>r.id===item.ruleId);if(r&&!r.excludedDates.includes(item.date))r.excludedDates.push(item.date);}if(item.goalId&&item.amount>0){const g=next.goals.find(g=>g.id===item.goalId);if(g)g.saved=Math.max(0,g.saved-item.amount);}}}
      return save(next,"Suppression enregistrée.");}});
  }
  const accountOptions=b.accounts.map(a=><option key={a.id} value={a.id}>{a.name}</option>);
  const transactionRows=(items:Transaction[],full=false)=>items.map(t=><button type="button" className={`transaction-row ${full?"full":""}`} key={t.id} onClick={()=>open({type:"transaction",item:t})}><MerchantIcon label={t.label} merchantId={t.merchantId} fallback={<CategoryIcon category={t.category}/>}/><span className="transaction-title"><strong>{t.label}</strong><small>{full?b.accounts.find(a=>a.id===t.accountId)?.name:t.category}{t.ruleId&&<Repeat2 size={11}/>}</small></span>{full&&<span className="category-label">{t.category}</span>}<span className="transaction-amount"><strong className={t.amount>0?"positive":""}>{t.amount>0?"+":"−"}{m(Math.abs(t.amount))}</strong><small>{shortDate(t.date)}</small></span><ChevronRight className="row-chevron" size={15}/></button>);
  const upcoming=futureTransactions(b,shiftDate(today,1),shiftDate(today,60));
  const recent=[...b.transactions].filter(t=>t.date<=today).sort((a,b)=>b.date.localeCompare(a.date)||a.label.localeCompare(b.label));
  function exportCSV(){const rows=[["Date","Libellé","Montant","Catégorie","Compte","Note"],...b.transactions.map(t=>[t.date,csvCell(t.label),(t.amount/100).toFixed(2).replace(".",","),csvCell(t.category),csvCell(b.accounts.find(a=>a.id===t.accountId)?.name??""),csvCell(t.note)])];downloadFile("\uFEFF"+rows.map(r=>r.join(";")).join("\r\n"),`pecule-operations-${today}.csv`,"text/csv;charset=utf-8");}
  const modalTitle=modal?.type==="actions"?"Une action, en un geste.":modal?.type==="transaction"?(modal.item?"Le détail de l’opération":"Ajouter une opération"):modal?.type==="account"?(modal.item?"Modifier le compte":"Un nouveau compte"):modal?.type==="rule"?(modal.item?"Modifier la récurrence":"Prévoir une récurrence"):modal?.type==="goal"?(modal.item?"Modifier votre objectif":"Un projet à concrétiser"):modal?.type==="transfer"?"Enregistrer un virement":modal?.type==="contribution"?"Faire grandir votre projet":modal?.type==="import"?"Importer vos opérations":modal?.type==="start"?"Bienvenue chez vous.":modal?.type==="calculation"?"Un disponible qui a du sens.":modal?.type==="install"?"PECULE, à portée de main.":modal?.type==="confirm"?modal.title:"";
  async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!modal)return;setError("");const f=new FormData(e.currentTarget),v=(key:string)=>String(f.get(key)??"").trim(),amount=(key:string)=>parseAmount(v(key));const next=structuredClone(b);let success=false;
    if(modal.type==="start"){const nextBudget=emptyBudget(v("name"));const initial=amount("balance");if(initial===null){setError("Indiquez un solde valide.");return;}nextBudget.accounts=[{id:uid(),name:v("accountName"),bank:"",type:"current",openingBalance:initial,openingDate:today,color:colors[0]}];success=await save(nextBudget,"Votre budget est prêt. Bienvenue dans PECULE !",true);if(success){setMonth(today.slice(0,7));setPage("overview");}}
    if(modal.type==="account"){const balance=amount("balance");if(balance===null){setError("Indiquez un solde valide.");return;}const item:Account={id:modal.item?.id??uid(),name:v("name"),bank:v("bank"),type:v("type") as Account["type"],openingBalance:balance,openingDate:v("date"),color:v("color")};next.accounts=editItem(next.accounts,item);success=await save(next);}
    if(modal.type==="transaction"){const n=amount("amount");if(n===null||n<=0){setError("Le montant doit être supérieur à zéro.");return;}const old=modal.item;const item:Transaction={...old,id:old?.id??uid(),label:v("label"),amount:n*(v("direction")==="expense"?-1:1),date:v("date"),accountId:v("account"),category:v("category"),note:v("note"),...(v("merchantId")?{merchantId:v("merchantId")} : {}),...(old?.ruleId?{ruleId:old.ruleId}:{})};if(old?.ruleId&&old.date!==item.date){const r=next.rules.find(r=>r.id===old.ruleId);if(r&&!r.excludedDates.includes(old.date))r.excludedDates.push(old.date);}const acc=next.accounts.find(a=>a.id===item.accountId);if(acc&&item.balanceIncluded&&item.date>acc.openingDate){setError("Une opération historique doit rester comprise dans la date du solde de référence.");return;}if(acc&&!item.balanceIncluded&&item.date<acc.openingDate){setError("Cette date précède le solde de référence du compte. Modifiez d’abord sa date de référence.");return;}next.transactions=editItem(next.transactions,item);success=await save(next);}
    if(modal.type==="rule"){const n=amount("amount");if(n===null||n<=0){setError("Indiquez un montant supérieur à zéro.");return;}if(v("end")&&v("end")<v("date")){setError("La date de fin doit suivre la date de début.");return;}const item:Rule={id:modal.item?.id??uid(),label:v("label"),amount:n*(v("direction")==="expense"?-1:1),accountId:v("account"),category:v("category"),startDate:v("date"),endDate:v("end"),frequency:v("frequency") as Rule["frequency"],timing:v("timing") as Rule["timing"],day:Number(v("day")),active:modal.item?.active??true,holidays:v("holidays") as Rule["holidays"],excludedDates:modal.item?.excludedDates??[],...(v("merchantId")?{merchantId:v("merchantId")} : {})};next.rules=editItem(next.rules,item);success=await save(next);}
    if(modal.type==="goal"){const target=amount("target"),saved=amount("saved"),monthly=amount("monthly");if(target===null||target<=0||saved===null||saved<0||monthly===null||monthly<0){setError("Vérifiez les montants de votre objectif.");return;}next.goals=editItem(next.goals,{id:modal.item?.id??uid(),name:v("name"),target,saved,monthly,color:v("color"),icon:v("icon"),deadline:v("deadline")});success=await save(next);}
    if(modal.type==="transfer"||modal.type==="contribution"){const n=amount("amount");if(n===null||n<=0){setError("Indiquez un montant supérieur à zéro.");return;}const goal=modal.type==="contribution"?modal.goal:modal.goal;const from=v("from"),to=v("to");if(from===to||!from||!to){setError("Choisissez deux comptes différents.");return;}const fromAcc=b.accounts.find(a=>a.id===from),toAcc=b.accounts.find(a=>a.id===to);if(goal&&toAcc?.type!=="savings"){setError("Choisissez un compte d’épargne comme destination.");return;}if(goal&&fromAcc?.type==="savings"){setError("Choisissez un compte courant comme source pour réserver votre épargne.");return;}const date=v("date");if(goal&&date>today){setError("Un versement vers un objectif doit être daté d’aujourd’hui ou d’avant.");return;}if([fromAcc,toAcc].some(a=>a&&date<a.openingDate)){setError("La date doit suivre les soldes de référence des deux comptes.");return;}const transferId=uid();next.transactions.push({id:uid(),label:goal?`Épargne · ${goal.name}`:"Virement entre comptes",amount:-n,date,accountId:from,category:"Virement",note:v("note"),transferId},{id:uid(),label:goal?`Épargne · ${goal.name}`:"Virement entre comptes",amount:n,date,accountId:to,category:"Virement",note:v("note"),transferId,...(goal?{goalId:goal.id}:{})});if(goal)next.goals=next.goals.map(g=>g.id===goal.id?{...g,saved:g.saved+n}:g);success=await save(next,"Virement enregistré dans PECULE.");}
    if(success)setModal(null);
  }
  if(!loaded)return <div className="boot-screen"><img src="/favicon.svg" alt="PECULE"/><h1>Votre budget prend place.</h1><p>Un instant pour retrouver votre espace personnel.</p><LoaderCircle size={20} className="spin"/></div>;
  return <div className={`app-shell page-${page}`}>
    <aside className="sidebar"><a className="brand" href="/" onClick={e=>{e.preventDefault();navigate("overview");}} aria-label="PECULE, accueil"><img src="/favicon.svg" alt=""/><span>pecule<span className="brand-dot">.</span></span></a><div className="workspace-label">MON ESPACE PERSONNEL <LockKeyhole size={11}/></div><nav aria-label="Navigation principale">{nav.map(({id,label,icon:Icon})=><button type="button" key={id} onClick={()=>navigate(id)} className={`nav-item ${page===id?"active":""}`} aria-current={page===id?"page":undefined}><Icon size={19} strokeWidth={1.7}/><span>{label}</span>{id==="goals"&&b.goals.length>0&&<span className="nav-count">{b.goals.length}</span>}</button>)}</nav><div className="sidebar-bottom"><div className="sidebar-note"><span className="note-orbit"><Sparkles size={18}/></span><strong>Les petits pas font<br/>les grands projets.</strong><p>Un peu de clarté, chaque jour.</p></div><button type="button" className={`nav-item ${page==="settings"?"active":""}`} onClick={()=>navigate("settings")}><Settings2 size={19}/><span>Réglages</span></button><div className="profile"><span className="avatar">{(b.name||user?.name||"M").charAt(0).toUpperCase()}</span><span><strong>{demo?"Mon espace démo":b.name||"Mon espace"}</strong><small><span className={`status-dot ${!online?"offline":""}`}/>{demo?"Pour découvrir PECULE":!online?"Hors connexion":"Espace personnel"}</small></span><LockKeyhole size={14}/></div></div></aside>
    <div className="main-wrap"><header className="topbar"><div className="breadcrumb"><span>Mon espace</span><ChevronRight size={12}/><strong>{nav.find(n=>n.id===page)?.label??"Réglages"}</strong></div><a href="/" className="mobile-brand" onClick={e=>{e.preventDefault();navigate("overview");}}>pecule<span>.</span></a><div className="topbar-actions"><span className={`sync-state ${!online||loadError?"warning":""}`}>{saving?<LoaderCircle size={13} className="spin"/>:!online?<CloudOff size={14}/>:<Cloud size={14}/>}<span>{!online?"Hors connexion":saving?"Enregistrement…":loadError?"Connexion à vérifier":!loaded?"Chargement…":demo?"Démonstration":"Synchronisé"}</span></span><button className="icon-button" type="button" title={hidden?"Afficher les montants":"Masquer les montants"} aria-label={hidden?"Afficher les montants":"Masquer les montants"} onClick={()=>{setHidden(!hidden);localStorage.setItem("pecule-hide-amounts",hidden?"0":"1");}}>{hidden?<EyeOff size={19}/>:<Eye size={19}/>}</button><button type="button" className="mobile-settings icon-button" aria-label="Réglages" onClick={()=>navigate("settings")}><Settings2 size={19}/></button><button className="primary top-add" type="button" aria-label="Ajouter une opération" onClick={()=>b.accounts.length?open({type:"transaction"}):open({type:"account"})}><Plus size={17}/><span>Ajouter une opération</span></button></div></header>
    <main id="main-content">
      {demo&&<div className="demo-banner"><span><Sparkles size={14}/><span>Un aperçu de votre futur budget.<strong> Les données sont fictives.</strong></span></span><button type="button" disabled={!loaded} onClick={()=>hasBudget?void load():open({type:"start"})}>{hasBudget?"Retrouver mon budget":"Créer mon budget"}<ArrowRight size={14}/></button></div>}
      {loadError&&<div className="error-banner"><CircleAlert size={17}/><span>{sessionExpired?"Votre session a expiré. Reconnectez-vous pour retrouver votre budget.":"La synchronisation est indisponible. Rechargez vos données avant de les modifier."}</span>{sessionExpired?<a href="/sign-in">Me reconnecter</a>:<button type="button" onClick={()=>void load()}>Réessayer</button>}</div>}
      {!online&&<div className="error-banner"><CloudOff size={17}/><span>Vous êtes hors connexion. Les modifications nécessitent Internet.</span></div>}
      {page!=="overview"&&<div className="page-heading"><div><h1>{pageTitles[page]}</h1><p>{page==="plan"?"Vos besoins, vos envies et votre épargne, au même endroit.":page==="transactions"?"Les petits achats comme les grandes étapes.":page==="recurring"?"Les rentrées et les sorties d’argent, sans les surprises.":page==="accounts"?"Une vision claire de votre argent, où qu’il soit.":page==="goals"?"Chaque petit pas vous rapproche de ce qui compte.":"Un budget qui s’adapte à votre quotidien."}</p></div>{page!=="settings"&&page!=="plan"&&<button type="button" className="primary" onClick={()=>open({type:page==="accounts"?"account":page==="goals"?"goal":page==="recurring"?"rule":"transaction"})}><Plus size={16}/>{page==="accounts"?"Ajouter un compte":page==="goals"?"Créer un objectif":page==="recurring"?"Ajouter une récurrence":"Nouvelle opération"}</button>}</div>}
      {page==="overview"&&<ClarteDashboard budget={b} today={today} hidden={hidden} demo={demo} online={online} saving={saving} loadError={loadError} onToggleHidden={()=>{setHidden(!hidden);localStorage.setItem("pecule-hide-amounts",hidden?"0":"1");}} onSettings={()=>navigate("settings")} onAdd={()=>b.accounts.length?open({type:"transaction"}):open({type:"account"})} onCalculate={()=>open({type:"calculation"})} onAccounts={()=>navigate("accounts")} onAccount={a=>open({type:"account",item:a})} onTransaction={t=>open({type:"transaction",item:t})} onUpcoming={t=>{const rule=b.rules.find(r=>r.id===t.ruleId);open(rule?{type:"rule",item:rule}:{type:"transaction",item:t});}} onTransactions={()=>navigate("transactions")} onRecurring={()=>navigate("recurring")} onGoals={()=>navigate("goals")} onPlan={()=>navigate("plan")} onAddAccount={()=>open({type:"account"})} chart={<ProjectionChart budget={b} today={today} hidden={hidden}/>}/>}
      {page==="plan"&&<SpendingPlan budget={b} today={today} month={month} setMonth={setMonth} hidden={hidden} saving={saving} onSave={save} onOperations={()=>navigate("transactions")}/>}
      {page==="transactions"&&<><section className="metric-strip"><div><span>Revenus reçus ce mois-ci</span><strong className="positive">+{m(o.income)}</strong></div><div><span>Dépenses ce mois-ci</span><strong>{m(o.spent)}</strong></div><div><span>Solde des comptes courants</span><strong>{m(o.total)}</strong></div></section><section className="card transactions-card"><div className="toolbar"><div className="search-input"><Search size={17}/><input aria-label="Rechercher une opération" placeholder="Rechercher une opération…" value={query} onChange={e=>setQuery(e.target.value)}/>{query&&<button type="button" className="icon-button" aria-label="Effacer la recherche" onClick={e=>{setQuery("");e.currentTarget.parentElement?.querySelector("input")?.focus();}}><X size={16}/></button>}</div><div className="toolbar-actions"><button type="button" className="secondary compact" onClick={()=>open({type:"import"})}><Upload size={15}/>Importer</button><button type="button" className="icon-button" title="Exporter toutes les opérations en CSV" aria-label="Exporter en CSV" onClick={exportCSV}><Download size={18}/></button></div></div><div className="filter-bar"><div className="segmented"><button type="button" className={typeFilter==="all"?"selected":""} onClick={()=>setTypeFilter("all")}>Toutes</button><button type="button" className={typeFilter==="expense"?"selected":""} onClick={()=>setTypeFilter("expense")}>Dépenses</button><button type="button" className={typeFilter==="income"?"selected":""} onClick={()=>setTypeFilter("income")}>Revenus</button></div><select className="filter-select" aria-label="Filtrer par compte" value={accountFilter} onChange={e=>setAccountFilter(e.target.value)}><option value="all">Tous les comptes</option>{accountOptions}</select><div className="month-control"><button type="button" className="icon-button small" aria-label="Mois précédent" onClick={()=>setMonth(dateISO(new Date(Number(month.slice(0,4)),Number(month.slice(5,7))-2,1,12)).slice(0,7))}><ChevronLeft size={17}/></button><strong>{parseDate(month+"-01").toLocaleDateString("fr-FR",{month:"long",year:"numeric"})}</strong><button type="button" className="icon-button small" aria-label="Mois suivant" onClick={()=>setMonth(dateISO(new Date(Number(month.slice(0,4)),Number(month.slice(5,7)),1,12)).slice(0,7))}><ChevronRight size={17}/></button></div></div>{(()=>{const items=[...b.transactions].filter(t=>t.date.startsWith(month)&&(accountFilter==="all"||t.accountId===accountFilter)&&(typeFilter==="all"||(typeFilter==="expense"?t.amount<0:t.amount>0))&&(t.label+" "+t.category+" "+t.note).toLocaleLowerCase("fr").includes(query.toLocaleLowerCase("fr"))).sort((a,b)=>b.date.localeCompare(a.date));const groups=[...new Set(items.map(t=>t.date))];return items.length?<div className="transaction-groups">{groups.map(date=><div key={date}><div className="date-group">{dateLabel(date,today)}{date>today&&<span>À venir</span>}</div>{transactionRows(items.filter(t=>t.date===date),true)}</div>)}<div className="table-footer">{items.length} opération{items.length>1?"s":""} · Les virements internes sont exclus des revenus et dépenses.</div></div>:<Empty icon={Search} title="Rien pour le moment" description="Aucune opération ne correspond à cette période ou à vos filtres." action={<button type="button" className="text-button" onClick={()=>b.accounts.length?open({type:"transaction"}):open({type:"account"})}>Ajouter une opération <Plus size={14}/></button>}/>;})()}</section></>}
      {page==="recurring"&&<><div className="info-callout"><CalendarDays size={20}/><div><strong>Un salaire le dernier jour ouvré ? C’est prévu.</strong><p>Choisissez une date fixe ou le dernier jour du mois hors week-end et jours fériés. Les opérations sont ajoutées à leur échéance, à partir de la date choisie.</p></div></div>{[true,false].map(income=>{const rules=b.rules.filter(r=>(r.amount>0)===income);return <section className="recurring-section" key={String(income)}><div className="section-heading"><h2>{income?"Les rentrées d’argent":"Les dépenses récurrentes"}</h2><span>{rules.filter(r=>r.active).length} active{rules.filter(r=>r.active).length>1?"s":""}</span></div>{rules.length?<div className="rule-grid">{rules.map(r=>{const next=futureTransactions({...b,rules:[r],transactions:[]},shiftDate(today,1),shiftDate(today,370))[0];return <article className={`card rule-card ${!r.active?"paused":""}`} key={r.id}><div className="rule-top"><MerchantIcon label={r.label} merchantId={r.merchantId} fallback={<CategoryIcon category={r.category}/>}/><div className="card-actions"><button type="button" className="icon-button small" aria-label={`Modifier ${r.label}`} onClick={()=>open({type:"rule",item:r})}><Pencil size={15}/></button><button type="button" className="icon-button small" aria-label={`${r.active?"Mettre en pause":"Reprendre"} ${r.label}`} onClick={()=>{void save({...b,rules:b.rules.map(x=>x.id===r.id?{...x,active:!x.active}:x)},r.active?"Récurrence mise en pause.":"Récurrence réactivée.");}}>{r.active?<Pause size={15}/>:<Play size={15}/>}</button><button type="button" className="icon-button small" aria-label={`Supprimer ${r.label}`} onClick={()=>remove("rule",r.id)}><Trash2 size={15}/></button></div></div><h3>{r.label}</h3><p>{b.accounts.find(a=>a.id===r.accountId)?.name}</p><div className={`rule-amount ${income?"positive":""}`}>{income?"+":"−"}{m(Math.abs(r.amount))}<small>/{r.frequency==="weekly"?"semaine":r.frequency==="yearly"?"an":"mois"}</small></div><div className="rule-bottom"><span className={`status-pill ${!r.active?"neutral":""}`}><span/>{!r.active?"En pause":next?shortDate(next.date):"Terminée"}</span><small>{r.timing==="last-business-day"?"Dernier jour ouvré":r.frequency==="weekly"?"Chaque semaine":`Le ${r.day}`}</small></div></article>;})}</div>:<div className="card"><Empty icon={income?ArrowDownLeft:Repeat2} title={income?"Prévoyez votre prochain revenu":"Anticipez les sorties d’argent"} description={income?"Salaire, allocation, revenu complémentaire : chacun a son rythme.":"Loyer, abonnement, assurance… gardez une longueur d’avance."} action={<button type="button" className="text-button" onClick={()=>b.accounts.length?open({type:"rule"}):open({type:"account"})}>Ajouter une récurrence <Plus size={14}/></button>}/></div>}</section>;})}</>}
      {page==="accounts"&&<><section className="metric-strip"><div><span>Votre argent au total</span><strong>{m(o.total+o.saved)}</strong></div><div><span>Disponible sur comptes courants</span><strong>{m(o.total)}</strong></div><div><span>À l’abri sur l’épargne</span><strong>{m(o.saved)}</strong></div></section><div className="section-heading"><h2>Vos comptes, simplement</h2><button type="button" className="secondary compact" onClick={()=>b.accounts.length>=2?open({type:"transfer"}):setToast("Ajoutez un deuxième compte pour enregistrer un virement.")}><ArrowLeftRight size={15}/>Virement entre comptes</button></div><div className="account-grid">{b.accounts.map(a=><article className="card account-card" key={a.id}><div className="account-card-top"><span className="bank-icon large" style={{background:a.color+"13",color:a.color}}><Wallet size={24}/></span><div className="card-actions"><button type="button" className="icon-button small" aria-label={`Modifier ${a.name}`} onClick={()=>open({type:"account",item:a})}><Pencil size={15}/></button><button type="button" className="icon-button small" aria-label={`Supprimer ${a.name}`} onClick={()=>remove("account",a.id)}><Trash2 size={15}/></button></div></div><span className="account-kind">{a.type==="savings"?"COMPTE D’ÉPARGNE":a.type==="cash"?"ESPÈCES":"COMPTE COURANT"}</span><h3>{a.name}</h3><p>{a.bank||"Compte personnel"}</p><div className="account-balance">{m(accountBalance(b,a.id,today))}</div><div className="account-card-bottom"><span className="status-dot"/>Suivi manuel · Solde au {shortDate(today)}</div><button type="button" className="account-details-link" onClick={()=>{setAccountFilter(a.id);setTypeFilter("all");navigate("transactions");}}>Voir les opérations <ArrowRight size={14}/></button></article>)}<button className="add-tile" type="button" onClick={()=>open({type:"account"})}><span><Plus size={23}/></span><strong>Un compte de plus ?</strong><small>Courant, épargne ou espèces.<br/>À vous de choisir.</small></button></div><div className="info-callout subtle"><LockKeyhole size={19}/><div><strong>Chacun ses comptes, chacun son espace.</strong><p>Vos comptes sont liés à votre connexion personnelle. Ajouter un compte ici ne crée pas de connexion avec votre banque.</p></div></div></>}
      {page==="goals"&&<><div className="goal-intro"><div><span className="eyebrow">CE QUE VOUS CONSTRUISEZ</span><h2>{m(b.goals.reduce((s,g)=>s+g.saved,0),false)} <span>déjà consacrés à vos projets.</span></h2><p>Le suivi de vos objectifs est indépendant du solde de vos livrets.</p></div><div className="goal-intro-icon"><Sparkles size={32} strokeWidth={1.2}/></div></div><div className="goal-grid">{b.goals.map(g=>{const Icon=goalIcons[g.icon]??Sun,progress=Math.min(100,Math.max(0,g.saved/g.target*100));return <article className="card goal-card" key={g.id}><div className="goal-card-top"><span className="goal-icon" style={{background:g.color+"20",color:g.color}}><Icon size={25} strokeWidth={1.6}/></span><div className="card-actions"><button type="button" className="icon-button small" aria-label={`Modifier ${g.name}`} onClick={()=>open({type:"goal",item:g})}><Pencil size={15}/></button><button type="button" className="icon-button small" aria-label={`Supprimer ${g.name}`} onClick={()=>remove("goal",g.id)}><Trash2 size={15}/></button></div></div><h3>{g.name}</h3><p>{g.deadline?`À votre rythme, jusqu’au ${shortDate(g.deadline)} ${g.deadline.slice(0,4)}`:"Un projet qui avance à votre rythme"}</p><div className="goal-amount"><strong>{m(g.saved,false)}</strong><span>sur {m(g.target,false)}</span></div><div className="progress-track" role="progressbar" aria-label={`Progression de ${g.name}`} aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.round(progress)}><span style={{width:progress+"%",background:g.color}}/></div><div className="goal-progress-label"><span>{Math.round(progress)} % du chemin</span><strong>{m(g.monthly,false)} / mois réservés</strong></div><button type="button" className="secondary full-width" onClick={()=>open({type:"contribution",goal:g})}><Plus size={15}/>Enregistrer un versement</button></article>;})}<button className="add-tile" type="button" onClick={()=>open({type:"goal"})}><span><Plus size={23}/></span><strong>Et votre prochain projet ?</strong><small>Une envie, un voyage ou<br/>simplement l’esprit tranquille.</small></button></div><div className="info-callout subtle"><Info size={19}/><div><strong>Votre épargne reste un choix.</strong><p>Choisissez votre objectif et votre réserve mensuelle. Cette réserve réduit le disponible sans déplacer d’argent. Un versement enregistré entre un compte courant et un compte d’épargne réduit la réserve restante du mois.</p></div></div></>}
      {page==="settings"&&<div className="settings-grid"><section className="card settings-card"><h2>Mon quotidien</h2><p>Quelques repères pour un budget qui vous ressemble.</p><ValidatedForm onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget),reserve=parseAmount(String(f.get("reserve")));if(reserve===null||reserve<0){setError("La réserve doit être un montant positif ou nul.");return;}await save({...b,name:String(f.get("name")).trim(),settings:{...b.settings,horizon:f.get("horizon") as Budget["settings"]["horizon"],reserve,holidayCalendar:f.get("holidays") as Budget["settings"]["holidayCalendar"]}});}}><FormField label="Votre prénom"><input name="name" maxLength={60} defaultValue={b.name}/></FormField><FormField label="Calculer mon disponible jusqu’à…" hint="Sans salaire prévu, PECULE utilise la fin du mois."><select name="horizon" defaultValue={b.settings.horizon}><option value="salary">Mon prochain salaire</option><option value="month">La fin du mois</option></select></FormField><FormField label="Réserve complémentaire pour la période" hint="S’ajoute aux réserves mensuelles de vos objectifs. Ce montant est retiré du disponible sans mouvement bancaire."><span className="amount-input"><input type="number" name="reserve" min="0" max="1000000000" step="0.01" defaultValue={inputAmount(b.settings.reserve)}/><span>€</span></span></FormField><FormField label="Calendrier par défaut des nouvelles récurrences" hint="France : jours fériés nationaux, hors spécificités régionales. Chaque récurrence garde son propre calendrier."><select name="holidays" defaultValue={b.settings.holidayCalendar}><option value="FR">France · lundi à vendredi, hors jours fériés</option><option value="none">Lundi à vendredi · sans jours fériés</option></select></FormField>{error&&<div className="form-error" role="alert">{error}</div>}<button className="primary" type="submit" disabled={saving}>{saving?<LoaderCircle size={16} className="spin"/>:<Check size={16}/>}Enregistrer mes préférences</button></ValidatedForm></section><div className="settings-side"><ThemePicker/>{user&&<GoogleConnection email={user.email}/>}<section className="card settings-card"><span className="settings-icon"><Smartphone size={21}/></span><h2>Toujours à portée de main.</h2><p>Retrouvez PECULE sur votre écran d’accueil, comme une application.</p><button className="secondary full-width" type="button" onClick={()=>open({type:"install"})}>Installer PECULE <ArrowUpRight size={15}/></button></section><section className="card settings-card"><h2>Vos données vous appartiennent.</h2><p>{demo?"Vous explorez la démonstration. Aucune donnée de cette démo n’est enregistrée sur votre compte.":"Vos données sont enregistrées sur votre compte et synchronisées entre vos appareils. Elles ne sont pas partagées avec les autres utilisateurs."}</p><div className="settings-links"><button type="button" onClick={()=>downloadFile(JSON.stringify(b,null,2),`pecule-sauvegarde-${today}.json`,"application/json")}><Download size={16}/>Télécharger une sauvegarde JSON</button><button type="button" onClick={exportCSV}><Download size={16}/>Exporter mes opérations en CSV</button><label className="restore-backup"><Upload size={16}/>Restaurer une sauvegarde JSON<input type="file" accept=".json,application/json" onChange={async e=>{const file=e.target.files?.[0];if(!file)return;e.target.value="";if(file.size>4000000){setToast("La sauvegarde dépasse 4 Mo.");return;}try{const {budgetSchema}=await import("../lib/validation");const result=budgetSchema.safeParse(JSON.parse(await file.text()));if(!result.success)throw new Error("La sauvegarde PECULE est invalide.");const restored=result.data;open({type:"confirm",title:"Restaurer cette sauvegarde ?",message:"Cette sauvegarde remplacera votre budget actuel. Téléchargez d’abord votre budget si vous souhaitez le conserver.",action:()=>save(restored,"Votre sauvegarde a été restaurée.")});}catch(err){setToast(err instanceof Error?err.message:"Fichier illisible.");}}}/></label><button type="button" onClick={()=>{setBudget(demoBudget(today));setDemo(true);navigate("overview");}}><Sparkles size={16}/>Explorer la démonstration</button>{demo?<button type="button" onClick={()=>hasBudget?void load():open({type:"start"})}><ArrowRight size={16}/>{hasBudget?"Retrouver mon budget":"Créer mon budget personnel"}</button>:<a href="/sign-out" target="_top"><LogOut size={16}/>Me déconnecter</a>}</div></section><div className="settings-brand"><img src="/favicon.svg" alt=""/><span>PECULE <small>Votre argent, l’esprit léger. · v1.0</small></span></div></div></div>}
    </main></div>
    <div className="floating-actions"><button type="button" className="floating-action-trigger" aria-label="Ouvrir les actions" aria-haspopup="dialog" aria-expanded={modal?.type==="actions"} onClick={()=>open({type:"actions"})}><Plus size={22}/><span>Ajouter</span></button></div><nav className="mobile-nav floating-nav" aria-label="Navigation mobile">{nav.slice(0,2).map(({id,short,icon:Icon}:typeof nav[number])=><button type="button" key={id} className={page===id?"active":""} aria-current={page===id?"page":undefined} onClick={()=>navigate(id)}><Icon size={21} strokeWidth={1.7}/><span>{short}</span></button>)}<button type="button" className="dock-add" aria-label="Ouvrir les actions" aria-haspopup="dialog" aria-expanded={modal?.type==="actions"} onClick={()=>open({type:"actions"})}><span className="dock-add-icon"><Plus size={23}/></span><span>Ajouter</span></button>{nav.slice(2).map(({id,short,icon:Icon}:typeof nav[number])=><button type="button" key={id} className={page===id?"active":""} aria-current={page===id?"page":undefined} onClick={()=>navigate(id)}><Icon size={21} strokeWidth={1.7}/><span>{short}</span></button>)}</nav>
    {toast&&<div className="toast" role="status"><CheckCheck size={18}/><span>{toast}</span><button type="button" aria-label="Fermer la notification" onClick={()=>setToast("")}><X size={15}/></button></div>}
    {modal&&<div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget&&!saving)setModal(null);}}><div className={`modal ${modal.type==="import"?"wide":""} ${modal.type==="actions"?"actions-modal":""}`} ref={dialogRef} role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div className="modal-heading"><div><span className="eyebrow">{modal.type==="start"?"VOTRE NOUVEAU DÉPART":"UN PEU PLUS DE CLARTÉ"}</span><h2 id="dialog-title">{modalTitle}</h2></div><button type="button" className="icon-button" aria-label="Fermer" disabled={saving} onClick={()=>setModal(null)}><X size={21}/></button></div>
    {modal.type==="actions"&&<div className="quick-actions"><p className="form-intro">Les petites actions qui gardent votre budget au clair.</p><div className="quick-action-grid">{[{title:"Une dépense",hint:"Un achat à enregistrer",icon:ArrowUpRight,color:"#a77362",background:"#faf0ec",target:{type:"transaction",direction:"expense"},needsAccount:true},{title:"Un revenu",hint:"De l’argent qui arrive",icon:ArrowDownLeft,color:"#568d77",background:"#edf5f0",target:{type:"transaction",direction:"income"},needsAccount:true},{title:"Une récurrence",hint:"Un revenu ou une charge",icon:Repeat2,color:"#7d77a8",background:"#f1eff8",target:{type:"rule"},needsAccount:true},{title:"Un compte",hint:"Courant, épargne ou espèces",icon:Wallet,color:"#6888bb",background:"#edf3fc",target:{type:"account"},needsAccount:false},{title:"Un objectif",hint:"Une envie à concrétiser",icon:Sparkles,color:"#b18b55",background:"#faf4ea",target:{type:"goal"},needsAccount:false},{title:"Un import CSV",hint:"Vos opérations bancaires",icon:Upload,color:"#7388a2",background:"#eef2f7",target:{type:"import"},needsAccount:true}].map(({title,hint,icon:Icon,color,background,target,needsAccount})=><button type="button" key={title} className="quick-action" onClick={()=>{if(needsAccount&&!b.accounts.length){setToast("Ajoutez d’abord un compte pour enregistrer vos opérations.");open({type:"account"});}else open(target as Modal);}}><span className="quick-action-icon" style={{color,background}}><Icon size={22} strokeWidth={1.6}/></span><strong>{title}</strong><small>{hint}</small><ChevronRight size={13} className="quick-action-chevron"/></button>)}</div></div>}
    {modal.type==="start"&&<>{!user?<div className="sign-in-prompt"><span className="empty-icon"><LockKeyhole size={26}/></span><p>Connectez-vous pour créer votre espace personnel et retrouver vos données sur iPhone et ordinateur. Votre budget est accessible avec votre adresse e-mail et votre mot de passe.</p><a className="primary full-width" href="/sign-in" target="_top">Se connecter ou créer un compte <ArrowRight size={17}/></a><small>Les comptes de démonstration ne seront pas ajoutés à votre budget.</small></div>:<BudgetSetup name={user.name?.split(" ")[0]??""} onSave={save} onDone={()=>{setModal(null);setMonth(today.slice(0,7));setPage("overview");}}/>}</>}
    {modal.type==="transaction"&&<>{!b.accounts.length?<Empty icon={Wallet} title="Il vous faut d’abord un compte" description="Vos opérations seront rattachées au compte de votre choix." action={<button type="button" className="primary" onClick={()=>open({type:"account"})}>Ajouter un compte</button>}/>:modal.item?.transferId?<div className="transfer-detail"><CategoryIcon category="Virement"/><h3>{modal.item.label}</h3><strong className="detail-amount">{m(Math.abs(modal.item.amount))}</strong><p>{shortDate(modal.item.date)} · {b.accounts.find(a=>a.id===modal.item?.accountId)?.name}</p><div className="info-callout"><Info size={18}/><p>Ce mouvement relie deux comptes. Pour le corriger, supprimez le virement puis enregistrez-le à nouveau. Les deux écritures seront supprimées ensemble.</p></div><button type="button" className="danger full-width" onClick={()=>remove("transaction",modal.item!.id)}><Trash2 size={16}/>Supprimer ce virement</button></div>:<ValidatedForm onSubmit={submit}><div className="form-grid"><FormField label="Type"><select name="direction" onChange={e=>setMerchantDirection(e.target.value)} defaultValue={modal.item?modal.item.amount>0?"income":"expense":modal.direction??"expense"}><option value="expense">Dépense</option><option value="income">Revenu</option></select></FormField><FormField label="Montant"><AmountInput name="amount" defaultValue={modal.item?Math.abs(modal.item.amount):undefined}/></FormField></div><MerchantFields initialLabel={modal.item?.label} initialCategory={modal.item?.category} initialMerchantId={modal.item?.merchantId} direction={merchantDirection}/><div className="form-grid"><FormField label="Date"><input name="date" type="date" min="2000-01-01" max="2100-12-31" defaultValue={modal.item?.date??today} required/></FormField><FormField label="Compte"><select name="account" defaultValue={modal.item?.accountId??b.accounts[0]?.id}>{accountOptions}</select></FormField></div><FormField label="Une note ? (facultatif)"><textarea className="resize-none" style={{resize:"none",minHeight:120}} name="note" rows={2} maxLength={1000} defaultValue={modal.item?.note} placeholder="Un détail à garder en tête"/></FormField>{modal.item?.ruleId&&<p className="field-hint">Cette modification concerne uniquement cette échéance. La récurrence reste inchangée.</p>}{error&&<div className="form-error" role="alert">{error}</div>}<div className="form-actions">{modal.item&&<button type="button" className="danger-icon" aria-label="Supprimer cette opération" onClick={()=>remove("transaction",modal.item!.id)}><Trash2 size={18}/></button>}<button type="submit" className="primary" disabled={saving}>{saving?<LoaderCircle className="spin" size={16}/>:<Check size={16}/>}Enregistrer l’opération</button></div></ValidatedForm>}</>}
    {modal.type==="account"&&<ValidatedForm onSubmit={submit}><FormField label="Nom du compte"><input name="name" maxLength={120} required defaultValue={modal.item?.name} placeholder="Mon compte du quotidien"/></FormField><div className="form-grid"><FormField label="Type de compte"><select name="type" defaultValue={modal.item?.type??"current"}><option value="current">Compte courant</option><option value="savings">Compte d’épargne</option><option value="cash">Espèces</option></select></FormField><FormField label="Banque ou précision (facultatif)"><input name="bank" maxLength={120} defaultValue={modal.item?.bank} placeholder="Pour vous y retrouver"/></FormField></div><div className="form-grid"><FormField label="Solde de référence"><AmountInput name="balance" defaultValue={modal.item?.openingBalance} positive={false}/></FormField><FormField label="Date de référence"><input name="date" type="date" required min="2000-01-01" max={today} defaultValue={modal.item?.openingDate??today}/></FormField></div><p className="field-hint">Ce solde sert de point de départ. Les opérations ajoutées depuis cette date s’y ajoutent. Les récurrences automatiques commencent après cette date pour éviter de recompter ce qui est déjà inclus.</p><div className="field"><span>Votre couleur</span><div className="color-choices">{colors.map((c,i)=><label key={c} style={{background:c}} title={`Couleur ${i+1}`}><input type="radio" name="color" value={c} defaultChecked={modal.item?modal.item.color===c:i===b.accounts.length%colors.length} required/><Check size={17}/><span className="sr-only">Couleur {i+1}</span></label>)}</div></div>{error&&<div className="form-error" role="alert">{error}</div>}<div className="form-actions">{modal.item&&<button type="button" className="danger-icon" aria-label="Supprimer ce compte" onClick={()=>remove("account",modal.item!.id)}><Trash2 size={18}/></button>}<button type="submit" className="primary" disabled={saving}>{saving?<LoaderCircle size={16} className="spin"/>:<Check size={16}/>}Enregistrer le compte</button></div></ValidatedForm>}
    {modal.type==="rule"&&<>{!b.accounts.length?<Empty icon={Wallet} title="Commençons par un compte" description="Les récurrences seront rattachées à ce compte." action={<button type="button" className="primary" onClick={()=>open({type:"account"})}>Ajouter un compte</button>}/>:<ValidatedForm onSubmit={submit}><MerchantFields initialLabel={modal.item?.label} initialCategory={modal.item?.category} initialMerchantId={modal.item?.merchantId} direction={merchantDirection}/><div className="form-grid"><FormField label="Type"><select name="direction" onChange={e=>setMerchantDirection(e.target.value)} defaultValue={modal.item&&modal.item.amount>0?"income":"expense"}><option value="expense">Dépense récurrente</option><option value="income">Entrée d’argent récurrente</option></select></FormField><FormField label="Montant"><AmountInput name="amount" defaultValue={modal.item?Math.abs(modal.item.amount):undefined}/></FormField></div><div className="form-grid"><FormField label="Compte"><select name="account" defaultValue={modal.item?.accountId??b.accounts[0]?.id}>{accountOptions}</select></FormField></div><div className="form-grid"><FormField label="Fréquence"><select name="frequency" defaultValue={modal.item?.frequency??"monthly"}><option value="monthly">Chaque mois</option><option value="weekly">Chaque semaine</option><option value="yearly">Chaque année</option></select></FormField><FormField label="Règle de date"><select name="timing" defaultValue={modal.item?.timing??"date"}><option value="date">Jour fixe</option><option value="last-business-day">Dernier jour ouvré du mois</option></select></FormField></div><div className="form-grid"><FormField label="Jour du mois (pour une date fixe)" hint="Un jour absent du mois est ramené au dernier jour."><input name="day" type="number" min="1" max="31" required defaultValue={modal.item?.day??parseDate(today).getDate()}/></FormField><FormField label="Jours fériés à exclure"><select name="holidays" defaultValue={modal.item?.holidays??b.settings.holidayCalendar}><option value="FR">France · calendrier national</option><option value="none">Aucun · week-ends uniquement</option></select></FormField></div><div className="form-grid"><FormField label="À partir du"><input name="date" type="date" min="2000-01-01" max="2100-12-31" required defaultValue={modal.item?.startDate??shiftDate(today,1)}/></FormField><FormField label="Jusqu’au (facultatif)"><input name="end" type="date" min="2000-01-01" max="2100-12-31" defaultValue={modal.item?.endDate}/></FormField></div><p className="field-hint">Chaque semaine : le jour de la date de début est utilisé. Chaque année : le mois de début est utilisé. Les autres règles de date concernent les fréquences mensuelles et annuelles. Les opérations passées restent conservées après une modification.</p>{error&&<div className="form-error" role="alert">{error}</div>}<button type="submit" className="primary full-width" disabled={saving}>{saving?<LoaderCircle size={16} className="spin"/>:<Repeat2 size={16}/>}Enregistrer la récurrence</button></ValidatedForm>}</>}
    {modal.type==="goal"&&<ValidatedForm onSubmit={submit}><FormField label="Quel projet avez-vous en tête ?"><input name="name" maxLength={120} required placeholder="Un voyage, une sécurité, une envie…" defaultValue={modal.item?.name}/></FormField><div className="form-grid"><FormField label="Objectif à atteindre"><AmountInput name="target" defaultValue={modal.item?.target}/></FormField><FormField label="Déjà mis de côté"><span className="amount-input"><input name="saved" type="number" step="0.01" min="0" max="1000000000" required defaultValue={inputAmount(modal.item?.saved??0)}/><span>€</span></span></FormField></div><FormField label="À réserver chaque mois" hint="Facultatif : mettez 0 pour avancer librement. La réserve restante est retirée du disponible, sans effectuer de virement bancaire."><span className="amount-input"><input name="monthly" type="number" step="0.01" min="0" max="1000000000" required defaultValue={inputAmount(modal.item?.monthly??0)}/><span>€</span></span></FormField><FormField label="Une date en tête ? (facultatif)"><input name="deadline" type="date" min="2000-01-01" max="2100-12-31" defaultValue={modal.item?.deadline}/></FormField><div className="form-grid"><FormField label="Une petite touche personnelle"><select name="icon" defaultValue={modal.item?.icon??"sun"}><option value="sun">Un rayon de soleil</option><option value="shield">La tranquillité</option><option value="home">Un chez-soi</option><option value="plane">Une aventure</option><option value="sparkles">Une envie</option></select></FormField><div className="field"><span>Couleur</span><div className="color-choices">{colors.map((c,i)=><label key={c} style={{background:c}} title={`Couleur ${i+1}`}><input type="radio" name="color" value={c} defaultChecked={modal.item?modal.item.color===c:i===2} required/><Check size={17}/><span className="sr-only">Couleur {i+1}</span></label>)}</div></div></div><p className="field-hint">Le montant déjà mis de côté sert au suivi de cet objectif. Il ne modifie pas le solde de vos comptes.</p>{error&&<div className="form-error" role="alert">{error}</div>}<button type="submit" className="primary full-width" disabled={saving}>{saving?<LoaderCircle size={16} className="spin"/>:<Sparkles size={16}/>}Enregistrer mon objectif</button></ValidatedForm>}
    {(modal.type==="transfer"||modal.type==="contribution")&&<>{b.accounts.length<2||(modal.type==="contribution"&&(!b.accounts.some(a=>a.type==="savings")||!b.accounts.some(a=>a.type!=="savings")))?<Empty icon={Wallet} title="Deux comptes, un projet." description="Ajoutez un compte courant et un compte d’épargne pour enregistrer un versement. Vous pouvez aussi modifier le montant déjà mis de côté dans votre objectif." action={<button type="button" className="primary" onClick={()=>open({type:"account"})}>Ajouter un compte</button>}/>:<ValidatedForm onSubmit={submit}>{modal.type==="contribution"&&<div className="mini-project"><Sparkles size={19}/><strong>{modal.goal.name}</strong></div>}<FormField label="Montant"><AmountInput name="amount"/></FormField><FormField label="Depuis le compte"><select name="from" defaultValue={b.accounts.find(a=>a.type!=="savings")?.id}>{b.accounts.filter(a=>modal.type!=="contribution"||a.type!=="savings").map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select></FormField><FormField label="Vers le compte"><select name="to" defaultValue={b.accounts.find(a=>a.type==="savings")?.id??b.accounts[1]?.id}>{b.accounts.filter(a=>modal.type!=="contribution"||a.type==="savings").map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select></FormField><FormField label="Date du virement"><input type="date" name="date" required min="2000-01-01" max={modal.type==="contribution"?today:"2100-12-31"} defaultValue={today}/></FormField><FormField label="Note (facultatif)"><input name="note" maxLength={1000}/></FormField><div className="info-callout"><Info size={17}/><p>PECULE enregistre le mouvement dans votre budget. Aucun virement bancaire n’est effectué : réalisez-le depuis votre banque.</p></div>{error&&<div className="form-error" role="alert">{error}</div>}<button type="submit" className="primary full-width" disabled={saving}>{saving?<LoaderCircle size={16} className="spin"/>:<Check size={16}/>}Enregistrer le virement</button></ValidatedForm>}</>}
    {modal.type==="import"&&<BankImport budget={b} today={today} saving={saving} save={save} serverError={error} onDone={()=>setModal(null)} onAddAccount={()=>open({type:"account"})} downloadTemplate={()=>downloadFile("\uFEFFDate;Libellé;Montant;Catégorie;Devise\r\n"+today+";Exemple de courses;-42,50;Alimentation;EUR\r\n","pecule-modele.csv","text/csv;charset=utf-8")}/>}
    {modal.type==="calculation"&&<div className="calculation-detail"><p>Votre disponible indique ce que vous pouvez encore dépenser après vos engagements connus.</p><div><span>Comptes courants et espèces</span><strong>{m(o.total)}</strong></div><div><span>− Dépenses prévues jusqu’au {shortDate(o.end)}</span><strong>{m(o.expenses)}</strong></div><div><span>− Réserve d’épargne restante</span><strong>{m(o.reserve)}</strong></div><div className="calculation-total"><span>Votre marge de manœuvre</span><strong>{m(o.available)}</strong></div><p className="field-hint">Les revenus futurs ne sont pas ajoutés au disponible. Les comptes d’épargne sont exclus. Les dépenses non saisies et les achats imprévus ne sont pas anticipés. Les récurrences sont enregistrées automatiquement à leur date prévue ; vérifiez les montants par rapport à votre banque.</p><p className="field-hint">La réserve est celle de cette période : réserve complémentaire + montants mensuels de vos objectifs, diminués des versements d’épargne enregistrés ce mois-ci. Le montant par jour répartit le disponible positif sur les jours restants, aujourd’hui inclus.</p><button type="button" className="secondary full-width" onClick={()=>{setModal(null);navigate("settings");}}>Ajuster mes préférences <Settings2 size={15}/></button></div>}
    {modal.type==="install"&&<div className="install-content"><img src="/icons/icon-192.png" alt="PECULE"/><p>Un accès direct à votre budget depuis votre écran d’accueil.</p><ol><li><span>1</span><div><strong>Ouvrez PECULE dans Safari sur iPhone.</strong><p>Utilisez l’adresse du site publié.</p></div></li><li><span>2</span><div><strong>Ouvrez le menu de partage.</strong><p>Puis choisissez « Sur l’écran d’accueil ».</p></div></li><li><span>3</span><div><strong>Ajoutez PECULE.</strong><p>Activez l’ouverture comme application si l’option est proposée.</p></div></li></ol><div className="info-callout"><Cloud size={17}/><p>Une connexion Internet est nécessaire pour charger et modifier le budget. Vos données restent synchronisées sur votre compte.</p></div>{installPrompt&&<button type="button" className="primary full-width" onClick={async()=>{await installPrompt.prompt();await installPrompt.userChoice;setInstallPrompt(null);}}>Installer sur cet appareil <Download size={16}/></button>}</div>}
    {modal.type==="confirm"&&<div><p className="form-intro">{modal.message}</p>{error&&<div className="form-error" role="alert">{error}</div>}<div className="form-actions"><button type="button" className="secondary" disabled={saving} onClick={()=>setModal(null)}>Annuler</button><button type="button" className="danger" disabled={saving} onClick={async()=>{if(await modal.action())setModal(null);}}>{saving?<LoaderCircle size={16} className="spin"/>:<Trash2 size={16}/>}Confirmer</button></div></div>}
    </div></div>}
  </div>;
}

function ProjectionChart({budget,today,hidden}:{budget:Budget;today:string;hidden:boolean}){
  const [hover,setHover]=useState<number|null>(null);
  const accounts=budget.accounts.filter(a=>a.type!=="savings"),ids=new Set(accounts.map(a=>a.id));
  const total=accounts.reduce((s,a)=>s+accountBalance(budget,a.id,today),0);
  const future=futureTransactions(budget,shiftDate(today,1),shiftDate(today,30)).filter(t=>ids.has(t.accountId));
  const points=Array.from({length:31},(_,i)=>{const date=shiftDate(today,i);return {date,value:total+future.filter(t=>t.date<=date).reduce((s,t)=>s+t.amount,0)};});
  const max=Math.max(10000,...points.map(p=>p.value))*1.15,min=Math.min(0,...points.map(p=>p.value))*1.15;
  const width=640,height=176,pad=8;
  const xy=points.map((p,i)=>({x:pad+i*(width-2*pad)/30,y:12+(max-p.value)/(max-min)*(height-28)}));
  const path=xy.map((p,i)=>`${i?"L":"M"}${p.x.toFixed(2)},${p.y.toFixed(2)}`).join(" ");
  const index=hover??0;
  return <div className="projection"><div className="chart-summary"><strong>{hidden?"•••• €":money(points[index].value,false)}</strong><span>{hover===null?"sur vos comptes courants aujourd’hui":`solde prévu le ${shortDate(points[index].date)}`}</span></div><div className="chart-container"><div className="chart-axis">{[1,.5,0].map(t=><span key={t}>{hidden?"•••":money(Math.round(min+(max-min)*t),false)}</span>)}</div><svg className="projection-svg" viewBox={`0 0 ${width} ${height}`} role="img" aria-label={`Projection sur 30 jours : solde actuel ${hidden?"masqué":money(total)}, solde prévu ${hidden?"masqué":money(points[30].value)}.`} onPointerMove={e=>{const rect=e.currentTarget.getBoundingClientRect();setHover(Math.max(0,Math.min(30,Math.round((e.clientX-rect.left)/rect.width*30))));}} onPointerLeave={()=>setHover(null)}><defs><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#6687fa" stopOpacity=".17"/><stop offset="100%" stopColor="#6687fa" stopOpacity="0"/></linearGradient></defs>{[14,82,150].map(y=><line key={y} x1="0" x2={width} y1={y} y2={y} stroke="#eceff5" strokeDasharray="3 5"/>)}<path d={`${path} L${xy[30].x},${height} L${xy[0].x},${height} Z`} fill="url(#chartFill)"/><path d={path} fill="none" stroke="#5578ec" strokeWidth="2.5" strokeLinejoin="round" strokeLinecap="round"/><line x1={xy[index].x} x2={xy[index].x} y1="8" y2={height-10} stroke="#b1c0f6" strokeDasharray="3 4"/><circle cx={xy[index].x} cy={xy[index].y} r="4.5" fill="#5578ec" stroke="white" strokeWidth="3"/></svg></div><div className="chart-dates">{[0,7,14,21,30].map(i=><span key={i}>{i===0?"Aujourd’hui":shortDate(points[i].date)}</span>)}</div><div className="sr-only"><table><caption>Soldes prévus chaque semaine</caption><tbody>{[0,7,14,21,30].map(i=><tr key={i}><th>{shortDate(points[i].date)}</th><td>{hidden?"Masqué":money(points[i].value)}</td></tr>)}</tbody></table></div></div>;
}
